import { registerScrollType } from './ScrollCatalog';
import { ScrollItem, ScrollItemOptions } from './ScrollItem';

export type EnchantWeaponScrollOptions = ScrollItemOptions;

/**
 * Scroll of Enchant Weapon (`附魔武器卷軸`) — increases the currently equipped weapon's
 * damage by +1 (`+1..+5`); attempting to enchant a `+5` weapon evaporates and destroys it.
 */
export class EnchantWeaponScroll extends ScrollItem {
  public readonly scrollKind = 'enchant_weapon' as const;

  constructor(options: EnchantWeaponScrollOptions) {
    super({
      id: options.id ?? `enchant-weapon-scroll-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Scroll of Enchant Weapon',
      itemTypeId: 'enchant_weapon_scroll',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.2,
      description:
        options.description ??
        'Imbues your equipped weapon with +1 damage (up to +5; enchanting beyond +5 evaporates the weapon!).',
    });
  }

  public getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string {
    return lang === 'zh-TW' ? '裝備武器傷害 +1' : 'Weapon Dmg +1';
  }

  public override cloneWithAmount(newAmount: number, newId?: string): EnchantWeaponScroll {
    return new EnchantWeaponScroll({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
    });
  }
}

registerScrollType('enchant_weapon_scroll');
