import type { Actor, PrimaryAttributeKey, PrimaryAttributes } from '../entities/Actor';
import type { SeededRNG } from '../SeededRNG';
import { Item } from './Item';

export type EquipmentSlotId =
  | 'head'
  | 'body'
  | 'arms'
  | 'weapon'
  | 'shield'
  | 'feet'
  | 'amulet'
  | 'ring1'
  | 'ring2';

export const ALL_EQUIPMENT_SLOTS: readonly EquipmentSlotId[] = [
  'head',
  'body',
  'arms',
  'weapon',
  'shield',
  'feet',
  'amulet',
  'ring1',
  'ring2',
];

export type ArmorSlotId = 'head' | 'body' | 'arms' | 'shield' | 'feet';

export const ARMOR_EQUIPMENT_SLOTS: readonly ArmorSlotId[] = [
  'head',
  'body',
  'arms',
  'shield',
  'feet',
];

export const MAX_SAFE_ENCHANT_LEVEL = 5;

export function isArmorSlot(slot: EquipmentSlotId): slot is ArmorSlotId {
  return (ARMOR_EQUIPMENT_SLOTS as readonly string[]).includes(slot);
}

export type EquipCategory =
  | 'head'
  | 'body'
  | 'arms'
  | 'weapon'
  | 'shield'
  | 'feet'
  | 'amulet'
  | 'ring';

export interface WeaponDice {
  readonly count: number;
  readonly sides: number;
  readonly bonus?: number;
}

export const UNARMED_WEAPON_DICE: WeaponDice = {
  count: 1,
  sides: 2,
  bonus: 0,
};

export function formatWeaponDice(dice: WeaponDice): string {
  const count = Math.max(1, Math.floor(dice.count));
  const sides = Math.max(1, Math.floor(dice.sides));
  const bonus = Math.floor(dice.bonus ?? 0);
  if (bonus > 0) {
    return `${count}d${sides}+${bonus}`;
  }
  if (bonus < 0) {
    return `${count}d${sides}${bonus}`;
  }
  return `${count}d${sides}`;
}

export function rollWeaponDice(dice: WeaponDice, rng?: SeededRNG): number {
  const count = Math.max(1, Math.floor(dice.count));
  const sides = Math.max(1, Math.floor(dice.sides));
  const bonus = Math.floor(dice.bonus ?? 0);
  let sum = bonus;
  for (let i = 0; i < count; i++) {
    const dieRoll = rng ? rng.nextInt(1, sides) : Math.max(1, Math.ceil(sides / 2));
    sum += dieRoll;
  }
  return Math.max(1, sum);
}

export function computeThrownWeaponDamage(
  dice: WeaponDice,
  target: Actor,
  rng?: SeededRNG,
  attacker?: Actor,
  extraAttackBonus = 0
): number {
  const rolled = rollWeaponDice(dice, rng);
  const strBonus = attacker ? Math.floor(attacker.attributes.str * 0.5) : 0;
  const raw = rolled + strBonus + extraAttackBonus;
  return Math.max(1, raw - target.stats.physicalDefense);
}

export function canCategoryFitSlot(category: EquipCategory, slot: EquipmentSlotId): boolean {
  if (slot === 'ring1' || slot === 'ring2') {
    return category === 'ring';
  }
  return category === slot;
}

export function isArmorEquipCategory(category: EquipCategory): boolean {
  return (
    category === 'head' ||
    category === 'body' ||
    category === 'arms' ||
    category === 'shield' ||
    category === 'feet'
  );
}

export function formatEnchantedItemName(baseName: string, enchantLevel: number): string {
  const lvl = Math.max(0, Math.floor(enchantLevel));
  return lvl > 0 ? `${baseName} +${lvl}` : baseName;
}

export function interpolateEquipmentStatsDescription(template: string, statBadge: string): string {
  if (!template.includes('{stats}')) {
    return template;
  }
  if (!statBadge) {
    return template.replace(/\s*[（(]\{stats\}[)）]/g, '').replace(/\{stats\}/g, '');
  }
  return template.replace(/\{stats\}/g, statBadge);
}

export interface EquipmentCombatStats {
  readonly equipCategory?: EquipCategory;
  readonly weaponDice?: WeaponDice;
  readonly attackBonus?: number;
  readonly defenseBonus?: number;
  readonly magicDefenseBonus?: number;
  readonly accuracyBonus?: number;
  readonly critChanceBonus?: number;
  readonly evasionBonus?: number;
  readonly maxHpBonus?: number;
  readonly maxMpBonus?: number;
  readonly maxSpBonus?: number;
  readonly attributeBonuses?: Partial<PrimaryAttributes>;
}

export interface EquipmentStatProvider extends Item, EquipmentCombatStats {
  getStatBadge(lang: 'en' | 'zh-TW'): string;
}

export interface EquippableItem extends EquipmentStatProvider {
  readonly equipCategory: EquipCategory;
  readonly baseName?: string;
  readonly enchantLevel?: number;
  setEnchantLevel?(level: number): number;
}

const ATTR_BADGE_LABELS_ZH: Readonly<Record<PrimaryAttributeKey, string>> = {
  str: '力量',
  con: '體質',
  int: '智力',
  wis: '智慧',
  agi: '敏捷',
  luk: '幸運',
};

export function formatEquipmentStatBadge(
  stats: EquipmentCombatStats,
  lang: 'en' | 'zh-TW'
): string {
  const parts: string[] = [];

  if (stats.weaponDice) {
    const diceStr = formatWeaponDice(stats.weaponDice);
    parts.push(lang === 'zh-TW' ? `傷害 ${diceStr}` : `Dmg ${diceStr}`);
  }
  if (stats.attackBonus && stats.attackBonus !== 0) {
    const sign = stats.attackBonus > 0 ? '+' : '';
    parts.push(
      lang === 'zh-TW' ? `攻擊 ${sign}${stats.attackBonus}` : `ATK ${sign}${stats.attackBonus}`
    );
  }
  if (stats.defenseBonus && stats.defenseBonus !== 0) {
    const sign = stats.defenseBonus > 0 ? '+' : '';
    parts.push(
      lang === 'zh-TW' ? `防禦 ${sign}${stats.defenseBonus}` : `DEF ${sign}${stats.defenseBonus}`
    );
  }
  if (stats.magicDefenseBonus && stats.magicDefenseBonus !== 0) {
    const sign = stats.magicDefenseBonus > 0 ? '+' : '';
    parts.push(
      lang === 'zh-TW'
        ? `魔防 ${sign}${stats.magicDefenseBonus}`
        : `MDEF ${sign}${stats.magicDefenseBonus}`
    );
  }

  if (stats.attributeBonuses) {
    const attrOrder: PrimaryAttributeKey[] = ['str', 'con', 'int', 'wis', 'agi', 'luk'];
    for (const key of attrOrder) {
      const val = stats.attributeBonuses[key];
      if (val && val !== 0) {
        const sign = val > 0 ? '+' : '';
        parts.push(
          lang === 'zh-TW'
            ? `${ATTR_BADGE_LABELS_ZH[key]} ${sign}${val}`
            : `${key.toUpperCase()} ${sign}${val}`
        );
      }
    }
  }

  if (stats.maxHpBonus && stats.maxHpBonus !== 0) {
    const sign = stats.maxHpBonus > 0 ? '+' : '';
    parts.push(
      lang === 'zh-TW' ? `最大HP ${sign}${stats.maxHpBonus}` : `Max HP ${sign}${stats.maxHpBonus}`
    );
  }
  if (stats.maxMpBonus && stats.maxMpBonus !== 0) {
    const sign = stats.maxMpBonus > 0 ? '+' : '';
    parts.push(
      lang === 'zh-TW' ? `最大MP ${sign}${stats.maxMpBonus}` : `Max MP ${sign}${stats.maxMpBonus}`
    );
  }
  if (stats.maxSpBonus && stats.maxSpBonus !== 0) {
    const sign = stats.maxSpBonus > 0 ? '+' : '';
    parts.push(
      lang === 'zh-TW' ? `最大SP ${sign}${stats.maxSpBonus}` : `Max SP ${sign}${stats.maxSpBonus}`
    );
  }
  if (stats.accuracyBonus && stats.accuracyBonus !== 0) {
    const sign = stats.accuracyBonus > 0 ? '+' : '';
    parts.push(
      lang === 'zh-TW' ? `命中 ${sign}${stats.accuracyBonus}` : `ACC ${sign}${stats.accuracyBonus}`
    );
  }
  if (stats.critChanceBonus && stats.critChanceBonus !== 0) {
    const sign = stats.critChanceBonus > 0 ? '+' : '';
    parts.push(
      lang === 'zh-TW'
        ? `暴擊 ${sign}${stats.critChanceBonus}%`
        : `Crit ${sign}${stats.critChanceBonus}%`
    );
  }
  if (stats.evasionBonus && stats.evasionBonus !== 0) {
    const sign = stats.evasionBonus > 0 ? '+' : '';
    parts.push(
      lang === 'zh-TW' ? `閃避 ${sign}${stats.evasionBonus}` : `EVA ${sign}${stats.evasionBonus}`
    );
  }

  return parts.join(', ');
}

export function hasEquipmentStatBadge(item: Item): item is EquipmentStatProvider {
  return typeof (item as Partial<EquipmentStatProvider>).getStatBadge === 'function';
}

export function isEquippableItem(item: Item): item is EquippableItem {
  return (
    typeof (item as Partial<EquippableItem>).equipCategory === 'string' &&
    hasEquipmentStatBadge(item)
  );
}

export function canItemFitSlot(item: Item, slot: EquipmentSlotId): item is EquippableItem {
  return isEquippableItem(item) && canCategoryFitSlot(item.equipCategory, slot);
}
