import { Actor } from '../entities/Actor';
import { SeededRNG } from '../SeededRNG';
import { registerPotionType } from './PotionCatalog';
import { PotionItem, PotionItemOptions, PotionQuaffEffectResult } from './PotionItem';

export const DEFAULT_SEE_INVISIBLE_MIN_TURNS = 10;
export const DEFAULT_SEE_INVISIBLE_MAX_TURNS = 20;

export interface SeeInvisiblePotionOptions extends PotionItemOptions {
  readonly minTurns?: number;
  readonly maxTurns?: number;
}

/**
 * Potion of See Invisible (`看破隱形藥水`): grants 10–20 character turns of additive See Invisible (`seeInvisibleTurns`)
 * on its target when quaffed (+10 Satiety) or thrown, allowing sighted actors to perceive invisible creatures.
 */
export class SeeInvisiblePotion extends PotionItem {
  public readonly minTurns: number;
  public readonly maxTurns: number;

  constructor(options: SeeInvisiblePotionOptions) {
    const minTurns = Math.max(1, Math.round(options.minTurns ?? DEFAULT_SEE_INVISIBLE_MIN_TURNS));
    const maxTurns = Math.max(
      minTurns,
      Math.round(options.maxTurns ?? DEFAULT_SEE_INVISIBLE_MAX_TURNS)
    );
    super({
      id: options.id ?? `see-invisible-potion-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Potion of See Invisible',
      itemTypeId: 'see_invisible_potion',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.5,
      stackable: true,
      quaffSatietyBonus: options.quaffSatietyBonus,
      description:
        options.description ??
        `A crystal-clear ocular draught that sharpens its target's sight to perceive invisible creatures for ${minTurns}–${maxTurns} turns when quaffed or thrown.`,
    });
    this.minTurns = minTurns;
    this.maxTurns = maxTurns;
  }

  public override getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string {
    return lang === 'zh-TW'
      ? `看破隱形 ${this.minTurns}–${this.maxTurns}回合`
      : `See Invis ${this.minTurns}–${this.maxTurns}t`;
  }

  public applyToTarget(target: Actor, rng?: SeededRNG): number {
    if (!target.isAlive()) {
      return 0;
    }
    const prevTurns = target.seeInvisibleTurns;
    const rolledTurns = rng
      ? rng.nextInt(this.minTurns, this.maxTurns)
      : Math.floor(Math.random() * (this.maxTurns - this.minTurns + 1)) + this.minTurns;
    const nextTurns = target.addSeeInvisibleTurns(rolledTurns);
    return nextTurns > prevTurns ? nextTurns : 0;
  }

  public override applyQuaffEffect(target: Actor, rng?: SeededRNG): PotionQuaffEffectResult {
    const added = this.applyToTarget(target, rng);
    return {
      kind: 'see_invisible',
      observableEffect: added > 0,
      seeInvisibleTurnsAdded: added,
    };
  }

  public override cloneWithAmount(newAmount: number, newId?: string): SeeInvisiblePotion {
    const cloned = new SeeInvisiblePotion({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
      minTurns: this.minTurns,
      maxTurns: this.maxTurns,
      quaffSatietyBonus: this.quaffSatietyBonus,
    });
    cloned.spriteKey = this.spriteKey;
    return cloned;
  }

  public override serializeCustomData(): Record<string, unknown> {
    return {
      minTurns: this.minTurns,
      maxTurns: this.maxTurns,
    };
  }
}

registerPotionType('see_invisible_potion');
