import { registerScrollType } from './ScrollCatalog';
import { ScrollItem, ScrollItemOptions } from './ScrollItem';

export type IdentifyScrollOptions = ScrollItemOptions;

/**
 * Scroll of Identify (`鑑定卷軸`) — reveals the true identity of 1 unidentified item
 * in the player's inventory when read via `'r'`.
 */
export class IdentifyScroll extends ScrollItem {
  public readonly scrollKind = 'identify' as const;

  constructor(options: IdentifyScrollOptions) {
    super({
      id: options.id ?? `identify-scroll-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Scroll of Identify',
      itemTypeId: 'identify_scroll',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.2,
      description:
        options.description ??
        'A divination scroll that reveals the true identity of an unidentified item in your bag when read.',
    });
  }

  public getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string {
    return lang === 'zh-TW' ? '鑑定 1 件物品' : 'Identify 1 Item';
  }

  public override cloneWithAmount(newAmount: number, newId?: string): IdentifyScroll {
    return new IdentifyScroll({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
    });
  }
}

registerScrollType('identify_scroll');
