import { registerScrollType } from './ScrollCatalog';
import { ScrollItem, ScrollItemOptions } from './ScrollItem';

export type DestroyArmorScrollOptions = ScrollItemOptions;

/**
 * Scroll of Destroy Armor (`損毀防具卷軸`) — curses and randomly disintegrates 1 currently
 * equipped armor piece (`Head`, `Body`, `Arms`, `Shield`, or `Feet`).
 */
export class DestroyArmorScroll extends ScrollItem {
  public readonly scrollKind = 'destroy_armor' as const;

  constructor(options: DestroyArmorScrollOptions) {
    super({
      id: options.id ?? `destroy-armor-scroll-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Scroll of Destroy Armor',
      itemTypeId: 'destroy_armor_scroll',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.2,
      description:
        options.description ??
        'A ruinous hex scroll that randomly destroys one piece of armor you are currently wearing.',
    });
  }

  public getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string {
    return lang === 'zh-TW' ? '隨機摧毀 1 件防具' : 'Destroy 1 Armor';
  }

  public override cloneWithAmount(newAmount: number, newId?: string): DestroyArmorScroll {
    return new DestroyArmorScroll({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
    });
  }
}

registerScrollType('destroy_armor_scroll');
