import { ChickDown } from '../items';
import { DEFAULT_SOUL_DROP_RATE } from '../souls';
import { Point } from '../types';
import { DEFAULT_ENEMY_MEAT_DROP_CHANCE, Enemy } from './Enemy';

export interface ChickOptions {
  readonly id: string;
  readonly position: Point;
}

/**
 * Chick (`小雞`):
 * - Low-tier small critter with short sensing range (4 tiles) and light peck attacks.
 * - Cannot open or close doors (`canOpenDoors = false`).
 */
export class Chick extends Enemy {
  constructor(options: ChickOptions) {
    super({
      id: options.id,
      archetypeId: 'enemy_chick',
      name: 'Chick',
      position: options.position,
      spriteKey: 'enemy_chick',
      level: 1,
      xpReward: 10,
      movementType: 'walking',
      sensingRange: 4,
      canOpenDoors: false,
      scoreValue: 25,
      dropsMeat: true,
      meatDropChance: DEFAULT_ENEMY_MEAT_DROP_CHANCE,
      meatSatietyValue: 100,
      meatWeight: 1.5,
      soulDropId: 'fledgling',
      soulDropRate: DEFAULT_SOUL_DROP_RATE,
      trophyDrops: [
        {
          itemTypeId: 'chick_down',
          chance: 0.25,
          create: ({ id, position }) => new ChickDown({ id, position }),
        },
      ],
      attributes: {
        str: 4,
        con: 4,
        int: 2,
        wis: 2,
        agi: 10,
        luk: 5,
      },
    });
  }
}
