import { registerScrollType } from './ScrollCatalog';
import { ScrollItem, ScrollItemOptions } from './ScrollItem';

export type TeleportScrollOptions = ScrollItemOptions;

/**
 * Scroll of Teleport (`傳送卷軸`) — warps the reader to a random unoccupied trap-free
 * floor tile on the current dungeon layer (matching Teleport Trap behavior).
 */
export class TeleportScroll extends ScrollItem {
  public readonly scrollKind = 'teleport' as const;

  constructor(options: TeleportScrollOptions) {
    super({
      id: options.id ?? `teleport-scroll-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Scroll of Teleport',
      itemTypeId: 'teleport_scroll',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.2,
      description:
        options.description ??
        'A spatial displacement scroll that instantly teleports its reader across the current dungeon floor.',
    });
  }

  public getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string {
    return lang === 'zh-TW' ? '同層隨機傳送' : 'Floor Teleport';
  }

  public override cloneWithAmount(newAmount: number, newId?: string): TeleportScroll {
    return new TeleportScroll({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
    });
  }
}

registerScrollType('teleport_scroll');
