import { registerScrollType } from './ScrollCatalog';
import { ScrollItem, ScrollItemOptions } from './ScrollItem';

export type CreateMonsterScrollOptions = ScrollItemOptions;

/**
 * Scroll of Create Monster (`召喚怪物卷軸`) — conjures a floor-weighted monster onto
 * a random unoccupied passable tile adjacent to the reader.
 */
export class CreateMonsterScroll extends ScrollItem {
  public readonly scrollKind = 'create_monster' as const;

  constructor(options: CreateMonsterScrollOptions) {
    super({
      id: options.id ?? `create-monster-scroll-${Math.random().toString(36).slice(2, 7)}`,
      name: 'Scroll of Create Monster',
      itemTypeId: 'create_monster_scroll',
      position: options.position,
      amount: options.amount ?? 1,
      weight: options.weight ?? 0.2,
      description:
        options.description ??
        'A conjuration scroll that summons a dungeon monster onto an adjacent tile when read.',
    });
  }

  public getIdentifiedStatBadge(lang: 'en' | 'zh-TW'): string {
    return lang === 'zh-TW' ? '相鄰召喚怪物' : 'Summon Adjacent';
  }

  public override cloneWithAmount(newAmount: number, newId?: string): CreateMonsterScroll {
    return new CreateMonsterScroll({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this.description,
    });
  }
}

registerScrollType('create_monster_scroll');
