import { DEFAULT_ENEMY_ALERTED_TURNS, type Enemy } from '../enemies/Enemy';
import { Actor, ATTRIBUTE_EXERCISE_GAINS } from '../entities/Actor';
import type { GameWorld } from '../GameWorld';
import { isAdjacent } from '../types';
import { Action, ActionResult, DEFAULT_ACTION_TIME_COST, MELEE_SP_COST } from './Action';

/**
 * Resolves a melee physical attack from `attacker` against an adjacent `target` actor:
 * - Hit roll: clamp(85 + (attacker.accuracy - target.evasion), 15, 98)
 * - Crit roll: clamp(attacker.critChance - target.critAvoidance, 0, 75) -> 1.5x damage
 * - Damage: max(1, floor(attacker.physicalAttack - target.physicalDefense * 0.5))
 * - Removes defeated enemies from the world and timeline.
 */
export class MeleeAttackAction implements Action {
  public readonly type = 'melee_attack';
  public readonly target: Actor;

  constructor(target: Actor) {
    this.target = target;
  }

  public execute(attacker: Actor, world: GameWorld): ActionResult {
    if (!attacker.isAlive() || !this.target.isAlive()) {
      return { success: false, timeCost: 0, message: 'Target is no longer alive.' };
    }

    if (!isAdjacent(attacker.position, this.target.position)) {
      return { success: false, timeCost: 0, message: 'Target is out of melee range.' };
    }

    if (!attacker.consumeSp(MELEE_SP_COST, false)) {
      const noSpMsg = 'Not enough stamina (SP)!';
      if (attacker.isPlayer) {
        world.eventBus.log(noSpMsg, 'combat', world.timeline.currentTime, 'notEnoughStamina', {
          actor: attacker.logName,
          required: MELEE_SP_COST,
        });
      }
      return { success: false, timeCost: 0, message: noSpMsg };
    }

    const targetIncapacitated = this.target.isIncapacitated();
    const effectiveAccuracy =
      !attacker.isBlind() && !world.canActorPerceiveTarget(attacker, this.target)
        ? Math.floor(attacker.stats.accuracy * 0.5)
        : attacker.stats.accuracy;
    const effectiveEvasion =
      !targetIncapacitated &&
      !this.target.isBlind() &&
      !world.canActorPerceiveTarget(this.target, attacker)
        ? Math.floor(this.target.stats.evasion * 0.5)
        : this.target.stats.evasion;
    const hitChance = targetIncapacitated
      ? 100
      : Math.min(98, Math.max(15, 85 + (effectiveAccuracy - effectiveEvasion)));
    const hitRoll = world.nextRandom() * 100;

    const attackerLogToken = world.getActorLogToken(attacker);
    const defenderLogToken = world.getActorLogToken(this.target);
    const attackerNameCap = world.getActorDisplayName(attacker, true);
    const defenderNameLower = world.getActorDisplayName(this.target, false);
    const defenderNameCap = world.getActorDisplayName(this.target, true);

    if (!targetIncapacitated && hitRoll >= hitChance) {
      const missMsg = attacker.isPlayer
        ? `You attack ${defenderNameLower}, but miss.`
        : this.target.isPlayer
          ? `${attackerNameCap} attacks you, but misses.`
          : `${attackerNameCap} attacks ${defenderNameLower}, but misses.`;
      world.eventBus.log(missMsg, 'combat', world.timeline.currentTime, 'attackMissed', {
        attacker: attackerLogToken,
        defender: defenderLogToken,
      });
      attacker.exerciseAttribute('str', ATTRIBUTE_EXERCISE_GAINS.meleeMissStrXp);
      attacker.exerciseAttribute('agi', MELEE_SP_COST * ATTRIBUTE_EXERCISE_GAINS.agiXpPerSpSpent);
      return {
        success: true,
        timeCost: DEFAULT_ACTION_TIME_COST,
        message: missMsg,
      };
    }

    const critChance = Math.min(
      75,
      Math.max(0, attacker.stats.critChance - this.target.stats.critAvoidance)
    );
    const isCrit = world.nextRandom() * 100 < critChance;

    const rawAttack = attacker.rollMeleePhysicalAttack(world.rng);
    const baseDamage = Math.max(1, rawAttack - this.target.stats.physicalDefense);
    const finalDamage = isCrit
      ? Math.max(1, Math.round(baseDamage * attacker.stats.critMultiplier))
      : baseDamage;

    const actualDamage = Math.min(this.target.stats.hp, finalDamage);
    this.target.stats.hp = Math.max(0, this.target.stats.hp - finalDamage);
    world.emitCombatHitVisualEffect({
      kind: 'melee_hit',
      attacker,
      target: this.target,
      isCrit,
    });

    if (attacker.isPlayer) {
      world.recordDamageDealt(actualDamage);
    }
    if (this.target.isPlayer) {
      world.recordDamageTaken(actualDamage, attacker);
    }

    const hitMsg = isCrit
      ? attacker.isPlayer
        ? `Critical hit! You strike ${defenderNameLower} for ${finalDamage} damage!`
        : this.target.isPlayer
          ? `Critical hit! ${attackerNameCap} strikes you for ${finalDamage} damage!`
          : `Critical hit! ${attackerNameCap} strikes ${defenderNameLower} for ${finalDamage} damage!`
      : attacker.isPlayer
        ? `You attack ${defenderNameLower} for ${finalDamage} damage.`
        : this.target.isPlayer
          ? `${attackerNameCap} attacks you for ${finalDamage} damage.`
          : `${attackerNameCap} attacks ${defenderNameLower} for ${finalDamage} damage.`;

    world.eventBus.log(
      hitMsg,
      'combat',
      world.timeline.currentTime,
      isCrit ? 'attackCrit' : 'attackHit',
      {
        attacker: attackerLogToken,
        defender: defenderLogToken,
        damage: finalDamage,
      }
    );

    if (!this.target.isAlive()) {
      const defeatMsg = this.target.isPlayer
        ? 'You are defeated!'
        : `${defenderNameCap} is defeated!`;
      world.eventBus.log(
        defeatMsg,
        'combat',
        world.timeline.currentTime,
        'actorDefeated',
        {
          defender: defenderLogToken,
        }
      );
      if (!this.target.isPlayer) {
        const defeatedEnemy = this.target as Enemy;
        world.recordEnemyDefeated(defeatedEnemy);
        world.tryDropEnemyMeat(defeatedEnemy);
        world.tryDropEnemyTrophy(defeatedEnemy);
        world.tryAbsorbEnemySoul(defeatedEnemy);
        world.removeEnemy(defeatedEnemy.id);
      }
    } else if (actualDamage > 0) {
      this.target.exerciseAttribute('con', actualDamage * ATTRIBUTE_EXERCISE_GAINS.conXpPerHpLost);
      world.wakeActorFromSleepByDamage(this.target);
      if (attacker.isPlayer && !this.target.isPlayer) {
        (this.target as Enemy).alertToPlayer(DEFAULT_ENEMY_ALERTED_TURNS);
      }
    }

    attacker.exerciseAttribute('str', ATTRIBUTE_EXERCISE_GAINS.meleeHitStrXp);
    attacker.exerciseAttribute('agi', MELEE_SP_COST * ATTRIBUTE_EXERCISE_GAINS.agiXpPerSpSpent);

    return {
      success: true,
      timeCost: DEFAULT_ACTION_TIME_COST,
      message: hitMsg,
    };
  }
}
