import { Cheese } from '../items';
import { DEFAULT_SOUL_DROP_RATE } from '../souls';
import { Point } from '../types';
import { DEFAULT_ENEMY_MEAT_DROP_CHANCE, Enemy } from './Enemy';

export interface RatOptions {
  readonly id: string;
  readonly position: Point;
}

/**
 * Rat (`老鼠`):
 * - Level 3 sneaky dungeon rodent (`movementType = 'walking'`, `sensingRange = 7`, `canOpenDoors = false`).
 * - Stalk & Ambush AI: while pursuing or adjacent to `@` and not yet `Invisible` (`sp >= 10`), rolls 30% to cast
 *   the self-buff War Skill `Hide` (`隱匿`, +5 full turns of `Invisible`), committing 100% to pursuit/melee once stealthed.
 * - Independent death drops: 20% `Meat of Rat` (`+150` Satiety, `1.2 wt`), 10% non-perishable `Cheese` (`+100` Satiety, `0.8 wt`), and 5% `Scavenger` (`食腐`) Soul.
 */
export class Rat extends Enemy {
  constructor(options: RatOptions) {
    super({
      id: options.id,
      archetypeId: 'enemy_rat',
      name: 'Rat',
      position: options.position,
      spriteKey: 'enemy_rat',
      level: 3,
      xpReward: 50,
      movementType: 'walking',
      sensingRange: 7,
      canOpenDoors: false,
      scoreValue: 120,
      dropsMeat: true,
      meatDropChance: DEFAULT_ENEMY_MEAT_DROP_CHANCE,
      meatSatietyValue: 150,
      meatWeight: 1.2,
      soulDropId: 'scavenger',
      soulDropRate: DEFAULT_SOUL_DROP_RATE,
      warSkills: [{ skillId: 'hide', chance: 0.3 }],
      trophyDrops: [
        {
          itemTypeId: 'cheese',
          chance: 0.1,
          create: ({ id, position }) => new Cheese({ id, position }),
        },
      ],
      attributes: {
        str: 9,
        con: 7,
        int: 3,
        wis: 4,
        agi: 16,
        luk: 10,
      },
    });
  }
}
