function parseWeaponDiceData(raw: unknown): WeaponDice | undefined {
  if (!raw || typeof raw !== 'object') {
    return undefined;
  }
  const obj = raw as Record<string, unknown>;
  if (typeof obj.count === 'number' && typeof obj.sides === 'number') {
    return {
      count: obj.count,
      sides: obj.sides,
      ...(typeof obj.bonus === 'number' ? { bonus: obj.bonus } : {}),
    };
  }
  return undefined;
}

