function parseEquipmentCustomData(d: SerializedItem): {
  weaponDice?: WeaponDice;
  attackBonus?: number;
  defenseBonus?: number;
  magicDefenseBonus?: number;
  accuracyBonus?: number;
  critChanceBonus?: number;
  evasionBonus?: number;
  maxHpBonus?: number;
  maxMpBonus?: number;
  maxSpBonus?: number;
  attributeBonuses?: Record<string, number>;
  enchantLevel?: number;
} {
  let attributeBonuses: Record<string, number> | undefined;
  if (d.customData?.attributeBonuses && typeof d.customData.attributeBonuses === 'object') {
    attributeBonuses = {};
    for (const [k, v] of Object.entries(d.customData.attributeBonuses as Record<string, unknown>)) {
      if (typeof v === 'number') {
        attributeBonuses[k] = v;
      }
    }
  }
  return {
    weaponDice: parseWeaponDiceData(d.customData?.weaponDice),
    attackBonus:
      typeof d.customData?.attackBonus === 'number' ? d.customData.attackBonus : undefined,
    defenseBonus:
      typeof d.customData?.defenseBonus === 'number' ? d.customData.defenseBonus : undefined,
    magicDefenseBonus:
      typeof d.customData?.magicDefenseBonus === 'number'
        ? d.customData.magicDefenseBonus
        : undefined,
    accuracyBonus:
      typeof d.customData?.accuracyBonus === 'number' ? d.customData.accuracyBonus : undefined,
    critChanceBonus:
      typeof d.customData?.critChanceBonus === 'number'
        ? d.customData.critChanceBonus
        : undefined,
    evasionBonus:
      typeof d.customData?.evasionBonus === 'number' ? d.customData.evasionBonus : undefined,
    maxHpBonus:
      typeof d.customData?.maxHpBonus === 'number' ? d.customData.maxHpBonus : undefined,
    maxMpBonus:
      typeof d.customData?.maxMpBonus === 'number' ? d.customData.maxMpBonus : undefined,
    maxSpBonus:
      typeof d.customData?.maxSpBonus === 'number' ? d.customData.maxSpBonus : undefined,
    ...(attributeBonuses ? { attributeBonuses } : {}),
    enchantLevel:
      typeof d.customData?.enchantLevel === 'number' ? d.customData.enchantLevel : undefined,
  };
}

