import {
  DEFAULT_BLINDNESS_MAX_TURNS,
  DEFAULT_BLINDNESS_MIN_TURNS,
} from '../items/BlindnessPotion';
import {
  DEFAULT_PARALYZE_MAX_TURNS,
  DEFAULT_PARALYZE_MIN_TURNS,
} from '../items/ParalyzePotion';
import {
  DEFAULT_SLEEP_MAX_TURNS,
  DEFAULT_SLEEP_MIN_TURNS,
} from '../items/SleepPotion';
