export const TRAP_SEARCH_DISCOVER_INT_XP = 10;
export const PIT_ESCAPE_AGI_XP = 8;
export const REVEALED_TRAP_PATH_COST = 50;

export type MagicTrapNegativeEffectId = 'blind' | 'paralysis' | 'sleep';

export const MAGIC_TRAP_NEGATIVE_EFFECTS: readonly MagicTrapNegativeEffectId[] = [
  'blind',
  'paralysis',
  'sleep',
];

/**
 * Uniformly selects `1` negative special effect from `MAGIC_TRAP_NEGATIVE_EFFECTS` (`1/3` each).
 */
export function pickMagicTrapNegativeEffect(roll: number): MagicTrapNegativeEffectId {
  const clamped = Math.max(0, Math.min(0.999999999, roll));
  const idx = Math.floor(clamped * MAGIC_TRAP_NEGATIVE_EFFECTS.length);
  return MAGIC_TRAP_NEGATIVE_EFFECTS[idx] ?? 'blind';
}

/**
 * Applies the potion-equivalent negative effect (`Blind` `10-20t` via `max`, `Paralysis` `5-10t` non-reapply,
 * or `Sleep` `10-20t` non-reapply) onto `target` and returns the effective turns newly applied/refreshed (`0` if unchanged).
 */
export function applyMagicTrapEffectToActor(
  target: Actor,
  effectId: MagicTrapNegativeEffectId,
  rng: SeededRNG
): number {
  if (!target.isAlive()) {
    return 0;
  }
  switch (effectId) {
    case 'blind': {
      const prev = target.blindTurns;
      const turns = rng.nextInt(DEFAULT_BLINDNESS_MIN_TURNS, DEFAULT_BLINDNESS_MAX_TURNS);
      const next = target.addBlindTurns(turns);
      return next > prev ? next : 0;
    }
    case 'paralysis': {
      if (target.isParalyzed()) {
        return 0;
      }
      const turns = rng.nextInt(DEFAULT_PARALYZE_MIN_TURNS, DEFAULT_PARALYZE_MAX_TURNS);
      target.addParalysisTurns(turns);
      return turns;
    }
    case 'sleep': {
      if (target.isAsleep()) {
        return 0;
      }
      const turns = rng.nextInt(DEFAULT_SLEEP_MIN_TURNS, DEFAULT_SLEEP_MAX_TURNS);
      target.addSleepTurns(turns);
      return turns;
    }
  }
}

/**
 * Computes the probability `[0.15, 1.00]` of discovering an adjacent hidden trap when pressing `"s"`:
 * SearchChance(INT) = clamp(0.25 + 0.03 * INT, 0.15, 1.00)
 * - INT = 10 (starting Howard): 55%
 * - INT = 15: 70%
 * - INT = 20: 85%
 * - INT >= 25: 100%
 */
export function computeTrapSearchChance(intAttribute: number): number {
  const raw = 0.25 + 0.03 * intAttribute;
  return Math.min(1, Math.max(0.15, Number(raw.toFixed(6))));
}

/**
 * Computes the probability `[0.20, 0.95]` of climbing out of a Pitfall Trap when moving to an adjacent tile:
 * EscapeChance(AGI) = clamp(0.60 + 0.02 * (AGI - 10), 0.20, 0.95)
 * - AGI = 5: 50%
 * - AGI = 7: 54%
 * - AGI = 10 (starting Howard): 60%
 * - AGI = 15: 70%
 * - AGI = 20: 80%
 * - AGI >= 28: 95%
 */
export function computePitEscapeChance(agiAttribute: number): number {
  const raw = 0.6 + 0.02 * (agiAttribute - 10);
  return Math.min(0.95, Math.max(0.2, Number(raw.toFixed(6))));
}

/**
 * Computes how many hidden traps spawn on a procedurally generated dungeon floor:
 * 8 + floor(floorNumber / 2)  (Floor 1 -> 8, Floor 2 -> 9, ..., Floor 10 -> 13)
 */
export function computeFloorTrapSpawnCount(floorNumber: number): number {
  const safeFloor = Math.max(1, Math.floor(floorNumber));
  return 8 + Math.floor(safeFloor / 2);
}

/**
 * Rolls raw physical damage dealt by a Spike Trap on `floorNumber`:
 * 2d6 + 4 + 2 * (floorNumber - 1)
 */
export function rollSpikeTrapRawDamage(floorNumber: number, rng: SeededRNG): number {
  const safeFloor = Math.max(1, Math.floor(floorNumber));
  const d1 = rng.nextInt(1, 6);
  const d2 = rng.nextInt(1, 6);
  return d1 + d2 + 4 + 2 * (safeFloor - 1);
}

/**
 * Rolls raw physical falling damage dealt by a Pitfall Trap on `floorNumber`:
 * 1d6 + 3 + (floorNumber - 1)
 */
export function rollPitfallTrapRawDamage(floorNumber: number, rng: SeededRNG): number {
  const safeFloor = Math.max(1, Math.floor(floorNumber));
  return rng.nextInt(1, 6) + 3 + (safeFloor - 1);
}

export interface TrapDefinition {
  readonly trapTypeId: string;
  readonly nameEn: string;
  readonly nameZh: string;
  readonly descriptionEn: string;
  readonly descriptionZh: string;
  readonly spriteKey: string;
  readonly spawnWeight: number;
  readonly affectedMovementTypes: readonly MovementType[];
  /** `null` = infinite/persistent trap; integer `>= 1` = finite charges before breaking. */
  readonly defaultUsesRemaining: number | null;
}

export interface SerializedTrap {
  readonly id: string;
  readonly trapTypeId: string;
  readonly position: Point;
  readonly revealed: boolean;
  readonly usesRemaining: number | null;
}

export interface TrapProps {
  readonly id: string;
  readonly trapTypeId: string;
  readonly nameEn: string;
  readonly nameZh: string;
  readonly spriteKey: string;
  readonly position: Point;
  readonly revealed?: boolean;
  readonly usesRemaining?: number | null;
}

export class Trap {
  public readonly id: string;
  public readonly trapTypeId: string;
  public readonly nameEn: string;
  public readonly nameZh: string;
  public readonly spriteKey: string;
  public position: Point;
  public revealed: boolean;
  public usesRemaining: number | null;

  constructor(props: TrapProps) {
    this.id = props.id;
    this.trapTypeId = props.trapTypeId;
    this.nameEn = props.nameEn;
    this.nameZh = props.nameZh;
    this.spriteKey = props.spriteKey;
    this.position = { x: props.position.x, y: props.position.y };
    this.revealed = Boolean(props.revealed ?? false);
    this.usesRemaining =
      props.usesRemaining === undefined || props.usesRemaining === null
        ? null
        : Math.max(0, Math.floor(props.usesRemaining));
  }

  public isExhausted(): boolean {
    return this.usesRemaining !== null && this.usesRemaining <= 0;
  }

  public consumeUse(): void {
    if (this.usesRemaining !== null && this.usesRemaining > 0) {
      this.usesRemaining -= 1;
    }
  }

  public getLocalizedName(lang: 'en' | 'zh-TW'): string {
    return lang === 'zh-TW' ? this.nameZh : this.nameEn;
  }

  public clone(): Trap {
    return new Trap({
      id: this.id,
      trapTypeId: this.trapTypeId,
      nameEn: this.nameEn,
      nameZh: this.nameZh,
      spriteKey: this.spriteKey,
      position: { ...this.position },
      revealed: this.revealed,
      usesRemaining: this.usesRemaining,
    });
  }

  public serialize(): SerializedTrap {
    return {
      id: this.id,
      trapTypeId: this.trapTypeId,
      position: { x: this.position.x, y: this.position.y },
      revealed: this.revealed,
      usesRemaining: this.usesRemaining,
    };
  }

  public static deserialize(data: SerializedTrap): Trap {
    const def = getTrapDefinitionById(data.trapTypeId) ?? SPIKE_TRAP_DEFINITION;
    return new Trap({
      id: data.id,
      trapTypeId: def.trapTypeId,
      nameEn: def.nameEn,
      nameZh: def.nameZh,
      spriteKey: def.spriteKey,
      position: { x: data.position.x, y: data.position.y },
      revealed: Boolean(data.revealed),
      usesRemaining:
        data.usesRemaining === undefined ? def.defaultUsesRemaining : data.usesRemaining,
    });
  }
}

const trapRegistry = new Map<string, TrapDefinition>();

export function registerTrapDefinition(def: TrapDefinition): void {
  trapRegistry.set(def.trapTypeId, def);
}

export function getTrapDefinitionById(trapTypeId: string): TrapDefinition | undefined {
  return trapRegistry.get(trapTypeId);
}

export function getAllTrapDefinitions(): TrapDefinition[] {
  return Array.from(trapRegistry.values());
}

/**
 * Returns `true` iff stepping onto a trap of `trapTypeId` affects an actor with `movementType`.
 */
export function trapAffectsMovementType(
  trapTypeId: string,
  movementType: MovementType
): boolean {
  const def = getTrapDefinitionById(trapTypeId);
  if (!def) {
    return true;
  }
  return def.affectedMovementTypes.includes(movementType);
}

