/**
 * Selects a registered `trapTypeId` from `[0, 1)` `roll` weighted by `def.spawnWeight`
 * (`40%` Spike Trap, `25%` Pitfall Trap, `20%` Magic Trap, `15%` Teleport Trap).
 */
export function pickWeightedTrapTypeId(roll: number): string {
  const defs = getAllTrapDefinitions().filter((d) => d.spawnWeight > 0);
  if (defs.length === 0) {
    return SPIKE_TRAP_DEFINITION.trapTypeId;
  }
  const totalWeight = Number(defs.reduce((sum, d) => sum + d.spawnWeight, 0).toFixed(9));
  const clamped = Math.max(0, Math.min(0.999999999, roll)) * totalWeight;
  let cumulative = 0;
  for (let i = 0; i < defs.length; i++) {
    cumulative = Number((cumulative + defs[i].spawnWeight).toFixed(9));
    if (clamped < cumulative || i === defs.length - 1) {
      return defs[i].trapTypeId;
    }
  }
  return defs[defs.length - 1].trapTypeId;
}

export function createTrapInstance(
  trapTypeId: string,
  id: string,
  position: Point,
  revealed = false
): Trap {
  const def = getTrapDefinitionById(trapTypeId) ?? SPIKE_TRAP_DEFINITION;
  return new Trap({
    id,
    trapTypeId: def.trapTypeId,
    nameEn: def.nameEn,
    nameZh: def.nameZh,
    spriteKey: def.spriteKey,
    position,
    revealed,
    usesRemaining: def.defaultUsesRemaining,
  });
}
