import { DEFAULT_SOUL_DROP_RATE } from '../souls';
import { Point } from '../types';
import { DEFAULT_ENEMY_MEAT_DROP_CHANCE, Enemy } from './Enemy';

export interface CatOptions {
  readonly id: string;
  readonly position: Point;
}

/**
 * Cat (`野貓`):
 * - Level 4 cunning arcane wildcat (`movementType = 'walking'`, `sensingRange = 8`, `canOpenDoors = false`).
 * - Spell-Weaving AI: while perceiving `@` (`chebyshevDist <= effectiveSensingRange` or `alertedTurns > 0`),
 *   rolls proportionally across valid actions from:
 *   - 20% `Clever` (`狡詐`, 10 MP, +10 full turns of +50% INT min +3) when `!hasClever()`
 *   - 20% `Fireball` (`火球`, 12 MP, 8-tile Bresenham line-of-fire first-target magic blast)
 *   - 60% Melee (`MeleeAttackAction` if adjacent) or `A*` pursuit step toward `@`
 * - Independent death drops: 20% `Meat of Cat` (`+180` Satiety, `1.8 wt`) and 5% `Clever` (`狡詐`) Soul.
 */
export class Cat extends Enemy {
  constructor(options: CatOptions) {
    super({
      id: options.id,
      archetypeId: 'enemy_cat',
      name: 'Cat',
      position: options.position,
      spriteKey: 'enemy_cat',
      level: 4,
      xpReward: 85,
      movementType: 'walking',
      sensingRange: 8,
      canOpenDoors: false,
      scoreValue: 200,
      dropsMeat: true,
      meatDropChance: DEFAULT_ENEMY_MEAT_DROP_CHANCE,
      meatSatietyValue: 180,
      meatWeight: 1.8,
      soulDropId: 'clever',
      soulDropRate: DEFAULT_SOUL_DROP_RATE,
      magicSkills: [
        { skillId: 'clever', chance: 0.2 },
        { skillId: 'fireball', chance: 0.2 },
      ],
      attributes: {
        str: 10,
        con: 8,
        int: 10,
        wis: 8,
        agi: 17,
        luk: 12,
      },
    });
  }
}
