import type { Actor, PrimaryAttributes } from '../entities/Actor';
import type { SeededRNG } from '../SeededRNG';
import {
  computeThrownWeaponDamage,
  EquipCategory,
  formatEnchantedItemName,
  formatEquipmentStatBadge,
  interpolateEquipmentStatsDescription,
  isArmorEquipCategory,
  WeaponDice,
} from './EquipmentItem';
import { ConcreteItemOptions, Item, ItemCategory, ItemThrowHitResult } from './Item';

export interface EquipmentPieceOptions extends ConcreteItemOptions {
  readonly weaponDice?: WeaponDice;
  readonly attackBonus?: number;
  readonly defenseBonus?: number;
  readonly magicDefenseBonus?: number;
  readonly accuracyBonus?: number;
  readonly critChanceBonus?: number;
  readonly evasionBonus?: number;
  readonly maxHpBonus?: number;
  readonly maxMpBonus?: number;
  readonly maxSpBonus?: number;
  readonly attributeBonuses?: Partial<PrimaryAttributes>;
  readonly enchantLevel?: number;
}

interface EquipmentPieceSpec {
  readonly defaultPrefix: string;
  readonly name: string;
  readonly itemTypeId: string;
  readonly itemType: Extract<ItemCategory, 'weapon' | 'armor' | 'accessory'>;
  readonly equipCategory: EquipCategory;
  readonly spriteKey: string;
  readonly defaultWeight: number;
  readonly stackable: boolean;
  readonly defaultDescription: string;
  readonly defaultWeaponDice?: WeaponDice;
  readonly defaultAttackBonus?: number;
  readonly defaultDefenseBonus?: number;
  readonly defaultMagicDefenseBonus?: number;
  readonly defaultAccuracyBonus?: number;
  readonly defaultCritChanceBonus?: number;
  readonly defaultEvasionBonus?: number;
  readonly defaultMaxHpBonus?: number;
  readonly defaultMaxMpBonus?: number;
  readonly defaultMaxSpBonus?: number;
  readonly defaultAttributeBonuses?: Partial<PrimaryAttributes>;
}

abstract class BaseEquipmentPiece extends Item {
  public readonly equipCategory: EquipCategory;
  public readonly baseName: string;
  private readonly baseWeaponDice?: WeaponDice;
  public readonly attackBonus: number;
  private readonly baseDefenseBonus: number;
  public readonly magicDefenseBonus: number;
  public readonly accuracyBonus: number;
  public readonly critChanceBonus: number;
  public readonly evasionBonus: number;
  public readonly maxHpBonus: number;
  public readonly maxMpBonus: number;
  public readonly maxSpBonus: number;
  public readonly attributeBonuses: Partial<PrimaryAttributes>;
  private _enchantLevel: number;

  protected constructor(spec: EquipmentPieceSpec, options: EquipmentPieceOptions) {
    const initialEnchant = Math.max(0, Math.floor(options.enchantLevel ?? 0));
    super({
      id: options.id ?? `${spec.defaultPrefix}-${Math.random().toString(36).slice(2, 7)}`,
      name: formatEnchantedItemName(spec.name, initialEnchant),
      itemTypeId: spec.itemTypeId,
      itemType: spec.itemType,
      position: options.position,
      spriteKey: spec.spriteKey,
      amount: options.amount ?? 1,
      weight: options.weight ?? spec.defaultWeight,
      stackable: spec.stackable,
      description: options.description ?? spec.defaultDescription,
    });
    this.equipCategory = spec.equipCategory;
    this.baseName = spec.name;
    const rawDice = options.weaponDice ?? spec.defaultWeaponDice;
    this.baseWeaponDice = rawDice ? { ...rawDice } : undefined;
    this.attackBonus = options.attackBonus ?? spec.defaultAttackBonus ?? 0;
    this.baseDefenseBonus = options.defenseBonus ?? spec.defaultDefenseBonus ?? 0;
    this.magicDefenseBonus = options.magicDefenseBonus ?? spec.defaultMagicDefenseBonus ?? 0;
    this.accuracyBonus = options.accuracyBonus ?? spec.defaultAccuracyBonus ?? 0;
    this.critChanceBonus = options.critChanceBonus ?? spec.defaultCritChanceBonus ?? 0;
    this.evasionBonus = options.evasionBonus ?? spec.defaultEvasionBonus ?? 0;
    this.maxHpBonus = options.maxHpBonus ?? spec.defaultMaxHpBonus ?? 0;
    this.maxMpBonus = options.maxMpBonus ?? spec.defaultMaxMpBonus ?? 0;
    this.maxSpBonus = options.maxSpBonus ?? spec.defaultMaxSpBonus ?? 0;
    this.attributeBonuses = {
      ...(spec.defaultAttributeBonuses ?? {}),
      ...(options.attributeBonuses ?? {}),
    };
    this._enchantLevel = initialEnchant;
  }

  public override get description(): string {
    return interpolateEquipmentStatsDescription(this._description, this.getStatBadge('en'));
  }

  public get enchantLevel(): number {
    return this._enchantLevel;
  }

  public setEnchantLevel(level: number): number {
    this._enchantLevel = Math.max(0, Math.floor(level));
    this.name = formatEnchantedItemName(this.baseName, this._enchantLevel);
    return this._enchantLevel;
  }

  public get weaponDice(): WeaponDice | undefined {
    if (!this.baseWeaponDice) {
      return undefined;
    }
    const bonusOffset = this.equipCategory === 'weapon' ? this._enchantLevel : 0;
    return {
      count: this.baseWeaponDice.count,
      sides: this.baseWeaponDice.sides,
      bonus: (this.baseWeaponDice.bonus ?? 0) + bonusOffset,
    };
  }

  public get defenseBonus(): number {
    return (
      this.baseDefenseBonus +
      (isArmorEquipCategory(this.equipCategory) ? this._enchantLevel : 0)
    );
  }

  public getStatBadge(lang: 'en' | 'zh-TW'): string {
    return formatEquipmentStatBadge(
      {
        weaponDice: this.weaponDice,
        attackBonus: this.attackBonus,
        defenseBonus: this.defenseBonus,
        magicDefenseBonus: this.magicDefenseBonus,
        accuracyBonus: this.accuracyBonus,
        critChanceBonus: this.critChanceBonus,
        evasionBonus: this.evasionBonus,
        maxHpBonus: this.maxHpBonus,
        maxMpBonus: this.maxMpBonus,
        maxSpBonus: this.maxSpBonus,
        attributeBonuses: this.attributeBonuses,
      },
      lang
    );
  }

  public override applyThrowHit(
    target: Actor,
    rng?: SeededRNG,
    attacker?: Actor
  ): ItemThrowHitResult {
    const effDice = this.weaponDice;
    if (this.equipCategory === 'weapon' && effDice) {
      return {
        damageDealt: computeThrownWeaponDamage(
          effDice,
          target,
          rng,
          attacker,
          this.attackBonus
        ),
      };
    }
    return { damageDealt: 0 };
  }

  protected buildCloneOptions(newAmount: number, newId?: string): EquipmentPieceOptions {
    return {
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this._description,
      ...(this.baseWeaponDice ? { weaponDice: { ...this.baseWeaponDice } } : {}),
      attackBonus: this.attackBonus,
      defenseBonus: this.baseDefenseBonus,
      magicDefenseBonus: this.magicDefenseBonus,
      accuracyBonus: this.accuracyBonus,
      critChanceBonus: this.critChanceBonus,
      evasionBonus: this.evasionBonus,
      maxHpBonus: this.maxHpBonus,
      maxMpBonus: this.maxMpBonus,
      maxSpBonus: this.maxSpBonus,
      attributeBonuses: { ...this.attributeBonuses },
      enchantLevel: this._enchantLevel,
    };
  }

  public override serializeCustomData(): Record<string, unknown> {
    const hasAttrBonuses = Object.keys(this.attributeBonuses).length > 0;
    return {
      ...(this.baseWeaponDice ? { weaponDice: { ...this.baseWeaponDice } } : {}),
      ...(this.attackBonus !== 0 ? { attackBonus: this.attackBonus } : {}),
      ...(this.baseDefenseBonus !== 0 ? { defenseBonus: this.baseDefenseBonus } : {}),
      ...(this.magicDefenseBonus !== 0 ? { magicDefenseBonus: this.magicDefenseBonus } : {}),
      ...(this.accuracyBonus !== 0 ? { accuracyBonus: this.accuracyBonus } : {}),
      ...(this.critChanceBonus !== 0 ? { critChanceBonus: this.critChanceBonus } : {}),
      ...(this.evasionBonus !== 0 ? { evasionBonus: this.evasionBonus } : {}),
      ...(this.maxHpBonus !== 0 ? { maxHpBonus: this.maxHpBonus } : {}),
      ...(this.maxMpBonus !== 0 ? { maxMpBonus: this.maxMpBonus } : {}),
      ...(this.maxSpBonus !== 0 ? { maxSpBonus: this.maxSpBonus } : {}),
      ...(hasAttrBonuses ? { attributeBonuses: { ...this.attributeBonuses } } : {}),
      ...(this._enchantLevel > 0 ? { enchantLevel: this._enchantLevel } : {}),
    };
  }
}

