export class ChickDown extends BaseEquipmentPiece {
  constructor(options: EquipmentPieceOptions) {
    super(
      {
        defaultPrefix: 'chick-down',
        name: 'Chick Down',
        itemTypeId: 'chick_down',
        itemType: 'armor',
        equipCategory: 'head',
        spriteKey: 'item_chick_down',
        defaultWeight: 0.3,
        stackable: true,
        defaultEvasionBonus: 2,
        defaultDescription:
          'Soft, weightless chick down — wearable as light head padding ({stats}) or used to line crafted armor.',
      },
      options
    );
  }

  public override cloneWithAmount(newAmount: number, newId?: string): ChickDown {
    return new ChickDown(this.buildCloneOptions(newAmount, newId));
  }
}

