import { DEFAULT_SOUL_DROP_RATE } from '../souls';
import { Point } from '../types';
import { Enemy } from './Enemy';

export interface EarthSpiritOptions {
  readonly id: string;
  readonly position: Point;
}

/**
 * Earth Spirit (`土精靈`):
 * - Level 5 hovering stone elemental (`movementType = 'flying'`, `sensingRange = 8`, `canOpenDoors = true`).
 * - Geomantic Battle AI: while perceiving `@` (`chebyshevDist <= effectiveSensingRange` or `alertedTurns > 0`),
 *   rolls proportionally across valid actions from:
 *   - 40% `Shield` (`鐵壁`, 10 MP, +10 full character turns of +50% DEF min +5) when `!hasShield()`
 *   - 40% `Rock Missile` (`飛岩`, 10 MP, 8-tile Bresenham line-of-fire first-target stone projectile)
 *   - 20% Melee (`MeleeAttackAction` if adjacent) or `A*` pursuit step toward `@` (opening closed doors)
 * - Death drops: `dropsMeat = false` (0% meat) and 5% `Rock Missile` (`飛岩`) Soul.
 */
export class EarthSpirit extends Enemy {
  constructor(options: EarthSpiritOptions) {
    super({
      id: options.id,
      archetypeId: 'enemy_earth_spirit',
      name: 'Earth Spirit',
      position: options.position,
      spriteKey: 'enemy_earth_spirit',
      level: 5,
      xpReward: 130,
      movementType: 'flying',
      sensingRange: 8,
      canOpenDoors: true,
      scoreValue: 300,
      dropsMeat: false,
      soulDropId: 'rock_missile',
      soulDropRate: DEFAULT_SOUL_DROP_RATE,
      magicSkills: [
        { skillId: 'shield', chance: 0.4 },
        { skillId: 'rock_missile', chance: 0.4 },
      ],
      attributes: {
        str: 13,
        con: 14,
        int: 13,
        wis: 12,
        agi: 10,
        luk: 9,
      },
    });
  }
}
