import type { Actor } from '../entities/Actor';
import type { SeededRNG } from '../SeededRNG';
import {
  computeThrownWeaponDamage,
  EquipCategory,
  formatEnchantedItemName,
  formatEquipmentStatBadge,
  interpolateEquipmentStatsDescription,
  WeaponDice,
} from './EquipmentItem';
import { ConcreteItemOptions, Item, ItemThrowHitResult } from './Item';

export interface IronSwordOptions extends ConcreteItemOptions {
  readonly weaponDice?: WeaponDice;
  readonly attackBonus?: number;
  readonly enchantLevel?: number;
}

/**
 * Standard forged iron blade (`1d6 + 1` weapon damage) wielded in the `Weapon` slot.
 */
export class IronSword extends Item {
  public readonly equipCategory: EquipCategory = 'weapon';
  public readonly baseName = 'Iron Sword';
  private readonly baseWeaponDice: WeaponDice;
  public readonly attackBonus: number;
  private _enchantLevel: number;

  constructor(options: IronSwordOptions) {
    const initialEnchant = Math.max(0, Math.floor(options.enchantLevel ?? 0));
    super({
      id: options.id ?? `iron-sword-${Math.random().toString(36).slice(2, 7)}`,
      name: formatEnchantedItemName('Iron Sword', initialEnchant),
      itemTypeId: 'iron_sword',
      itemType: 'weapon',
      position: options.position,
      spriteKey: 'item_sword',
      amount: options.amount ?? 1,
      weight: options.weight ?? 4.0,
      stackable: false,
      description: options.description ?? 'A well-balanced forged iron blade ({stats}).',
    });
    this.baseWeaponDice = options.weaponDice ?? { count: 1, sides: 6, bonus: 1 };
    this.attackBonus = options.attackBonus ?? 0;
    this._enchantLevel = initialEnchant;
  }

  public override get description(): string {
    return interpolateEquipmentStatsDescription(this._description, this.getStatBadge('en'));
  }

  public get enchantLevel(): number {
    return this._enchantLevel;
  }

  public setEnchantLevel(level: number): number {
    this._enchantLevel = Math.max(0, Math.floor(level));
    this.name = formatEnchantedItemName(this.baseName, this._enchantLevel);
    return this._enchantLevel;
  }

  public get weaponDice(): WeaponDice {
    return {
      count: this.baseWeaponDice.count,
      sides: this.baseWeaponDice.sides,
      bonus: (this.baseWeaponDice.bonus ?? 0) + this._enchantLevel,
    };
  }

  public getStatBadge(lang: 'en' | 'zh-TW'): string {
    return formatEquipmentStatBadge(
      {
        weaponDice: this.weaponDice,
        attackBonus: this.attackBonus,
      },
      lang
    );
  }

  public override applyThrowHit(
    target: Actor,
    rng?: SeededRNG,
    attacker?: Actor
  ): ItemThrowHitResult {
    return {
      damageDealt: computeThrownWeaponDamage(
        this.weaponDice,
        target,
        rng,
        attacker,
        this.attackBonus
      ),
    };
  }

  public override cloneWithAmount(newAmount: number, newId?: string): IronSword {
    return new IronSword({
      id: newId ?? `${this.id}-${Math.random().toString(36).slice(2, 7)}`,
      position: { x: this.position.x, y: this.position.y },
      amount: newAmount,
      weight: this.weight,
      description: this._description,
      weaponDice: { ...this.baseWeaponDice },
      attackBonus: this.attackBonus,
      enchantLevel: this._enchantLevel,
    });
  }

  public override serializeCustomData(): Record<string, unknown> {
    return {
      weaponDice: { ...this.baseWeaponDice },
      ...(this.attackBonus !== 0 ? { attackBonus: this.attackBonus } : {}),
      ...(this._enchantLevel > 0 ? { enchantLevel: this._enchantLevel } : {}),
    };
  }
}
